import{z as A,x as i,o as r,c as l,q as t,j as s,D as e,d as o,s as n,S as p}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"trapframe","description":"","frontmatter":{"title":"trapframe","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/trapframe.md","filePath":"cs/trapframe.md","lastUpdated":1791413859000}'),B={name:"cs/trapframe.md"};function d(m,a,c,f,_,h){const E=i("Mermaid");return r(),l("div",null,[a[2]||(a[2]=t('<h1 id="trapframe" tabindex="-1">trapframe <a class="header-anchor" href="#trapframe" aria-label="Permalink to &quot;trapframe&quot;">​</a></h1><div class="epigraph"><p>陷入必须把用户可见的寄存器收进内核栈上的一帧，返回时原样写回；否则用户程序会在随机寄存器里醒来。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Bovet and Cesati 整理</footer></div><p><a href="/cs/vdso">上一课</a>让部分查询免陷入。一旦执行陷入指令或发生异常、中断，<a href="/cs/exception-interrupt-entry">异常入口</a>会切特权并跳到固定向量。缺口是：硬件只保证保存 PC 与原因；<strong>通用寄存器、用户栈指针、返回后的特权级</strong>要由软件收成一份可恢复的帧——trapframe。本课只钉这帧，不走系统调用分发。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户线程的 <code>a0</code>–<code>a7</code> 里可能正是系统调用参数，也可能是被中断的普通计算。若内核随手用这些寄存器当临时量，返回用户时计算已坏。跨线程切换还要把帧与<a href="/cs/process-image">进程映像</a>里的其余状态接上。缺口不是新的环，而是内核栈顶那块<strong>与 ISA 寄存器一一对应的内存映像</strong>。</p><p><span class="marginnote">数字实例：RISC-V 有 32 个通用寄存器，一份 trapframe 至少要存 32 × 8 字节 = 256 字节，再加 PC 与状态寄存器约 280 字节——每次陷入都原样搬一遍，这是陷入比函数调用贵几十倍的原因之一。</span></p><p>本课不把每一种架构的 <code>pt_regs</code> 字段表背完。</p><p><span class="marginnote">trapframe 通常压在该线程的内核栈上。切换线程时换内核栈指针，等于换到另一份帧。用户栈指针是帧里的一个字段，不是内核正在用的栈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>入口：硬件或极短汇编保存 PC、状态寄存器，再把通用寄存器写入帧；内核 C 代码只通过帧读写用户状态。返回：按帧恢复，执行 <code>sret</code>/<code>iret</code>，特权降回用户。系统调用的返回值写入帧中的返回值槽，再走同一条恢复路径。中断与自愿陷入共用帧布局，便于同一套返回代码。</p><p><span class="marginnote">术语翻译：trapframe 就是内核给用户线程寄存器拍的快照清单——把通用寄存器连同 PC、状态位逐项抄进内核栈顶的结构，返回时照单写回，用户程序才能在原地继续。</span></p>',11)),(r(),s(p,null,{default:e(()=>[n(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRAP%5B%22%E9%99%B7%E5%85%A5%E6%88%96%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20SAVE%5B%22%E5%86%99%E5%85%A5%20trapframe%22%5D%0A%20%20SAVE%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%E7%94%A8%E5%B8%A7%E8%AF%BB%E5%86%99%E7%94%A8%E6%88%B7%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20K%20--%3E%20REST%5B%22%E6%8C%89%E5%B8%A7%E6%81%A2%E5%A4%8D%E5%B9%B6%E8%BF%94%E5%9B%9E%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><a href="/cs/calling-convention-stack">调用约定</a>的用户栈帧仍在用户页上；本课的对象是内核里那份架构状态副本。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了帧，内核可以在处理过程中调度：当前线程的用户寄存器不在 CPU 上，而在它的 trapframe 里。<a href="/cs/context-switch">上下文切换</a>换的是「哪份帧成为活的」，不另造一套寄存器含义。缺页、系统调用、设备 IRQ 都先落到同一形状的帧，再按原因分发——分发是下一课路径。</p><p>内核自己的调用用内核栈上的普通帧，不要与 trapframe 混名。本课只要求：凡从用户来，先有 trapframe。</p><p><span class="marginnote">常见误区：以为内核处理中断时用的是用户栈。陷入后 SP 已切到内核栈，trapframe 也压在这里；用户栈只是帧里的一个普通字段。混用两者曾是真实内核漏洞的经典起点。</span></p>',5)),(r(),s(p,null,{default:e(()=>[n(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%7B%22%E4%B8%BA%E4%BB%80%E4%B9%88%E8%BF%9B%E5%85%A5%E5%86%85%E6%A0%B8%EF%BC%9F%22%7D%20--%3E%20PG%5B%22%E7%BC%BA%E9%A1%B5%E5%BC%82%E5%B8%B8%22%5D%0A%20%20EVT%20--%3E%20SC%5B%22%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%E6%8C%87%E4%BB%A4%22%5D%0A%20%20EVT%20--%3E%20IRQ%5B%22%E8%AE%BE%E5%A4%87%E4%B8%AD%E6%96%AD%22%5D%0A%20%20PG%20--%3E%20TF%5B%22%E5%90%8C%E4%B8%80%E5%BD%A2%E7%8A%B6%E7%9A%84%20trapframe%22%5D%0A%20%20SC%20--%3E%20TF%0A%20%20IRQ%20--%3E%20TF%0A%20%20TF%20--%3E%20DISP%7B%22%E6%8C%89%E5%B8%A7%E9%87%8C%E7%9A%84%E5%8E%9F%E5%9B%A0%E5%AD%97%E6%AE%B5%E5%88%86%E5%8F%91%22%7D%0A%20%20DISP%20--%3E%20HAND%5B%22%E5%90%84%E8%87%AA%E7%9A%84%E5%A4%84%E7%90%86%E4%BE%8B%E7%A8%8B%3Cbr%2F%3E%E5%85%B1%E7%94%A8%E5%90%8C%E4%B8%80%E5%A5%97%E6%81%A2%E5%A4%8D%E4%BB%A3%E7%A0%81%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 FPU 惰性保存的全部 ABI，不把信号递送如何改用户 PC 提前讲完。也不讨论调试器改帧里的寄存器——那是更后的跟踪课。安全课关心「有没有漏存」；本课假定保存完整。</p><p>后课默认：进入内核时用户状态在 trapframe 里。用户按 ABI 请求服务之后，如何按号分发、拷贝参数、返回，下一课走<a href="/cs/syscall-path">系统调用路径</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>trapframe 是内核栈上的用户寄存器映像；返回必须按它恢复。</li><li>中断与系统调用共用帧布局；切换换的是哪份帧活着。</li><li>分发与参数拷贝是路径课的缺口。</li><li>出处：Tanenbaum and Bos, <em>MOS</em>；Bovet and Cesati。</li></ul>',5))])}const D=A(B,[["render",d]]);export{C as __pageData,D as default};
